// Kontrollerar F9b (k-028): knappen Läsläge finns i sidhuvudet med aria-pressed, CSS och skript är länkade
// före sidans egen stil, reglerna gäller bara när läget är på, och valet sparas bara i webbläsaren.
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const css = fs.readFileSync('public/css/laslage.css', 'utf8');
const js = fs.readFileSync('public/js/laslage.js', 'utf8');
const html = fs.readFileSync('public/index.html', 'utf8');
const knapp = (html.match(/<button[^>]+id="lasBtn"[^>]*>[^<]*<\/button>/) || [''])[0];
// Varje regel utom knappens egen ska börja med :root[data-laslage="pa"], annars ändras sidan för alla.
const regler = css.replace(/\/\*[\s\S]*?\*\//g, '').split('}').map((r) => r.split('{')[0].trim()).filter(Boolean);
const selektorer = regler.flatMap((r) => r.split(',').map((s) => s.trim()));
const krav = {
  knappFinns: /type="button"/.test(knapp) && />Läsläge</.test(knapp),
  knappTillstand: /aria-pressed="false"/.test(knapp),
  knappISidhuvudet: html.indexOf('id="lasBtn"') > html.indexOf('<header class="top"') && html.indexOf('id="lasBtn"') < html.indexOf('</header>'),
  cssLankad: html.includes('/css/laslage.css'),
  skriptISidhuvudet: html.indexOf('/js/laslage.js') > -1 && html.indexOf('/js/laslage.js') < html.indexOf('<style>'),
  baraNarPa: selektorer.every((s) => s.startsWith(':root[data-laslage="pa"]') || s.startsWith('#lasBtn')),
  storreText: /:root\[data-laslage="pa"\] body\s*\{[^}]*font-size:\s*20px/.test(css),
  radlangd: /\.ptext[\s\S]*?max-width:\s*62ch/.test(css),
  tavlan: /\.vp-cols\s*\{[^}]*minmax\(300px/.test(css) && /\.vp-detail\s*\{[^}]*font-size:\s*17px/.test(css),
  sparasLokalt: js.includes("localStorage") && js.includes("'laslage'"),
  ingetNatverk: !/fetch\(|XMLHttpRequest|sendBeacon|supabase|document\.cookie/.test(js),
  talLagringsfel: (js.match(/try\s*\{/g) || []).length >= 2,
  nyttPaLoom: fs.readFileSync('public/data/nytt.json', 'utf8').includes('Läsläge med större text'),
  aiMarkt: css.includes('Generated by AI, Directed by MS') && js.includes('Generated by AI, Directed by MS'),
};
const ok = Object.values(krav).every(Boolean);
console.log(JSON.stringify({ ...krav, ok }));
process.exit(ok ? 0 : 1);
